// This file is generated by AI.

//! 快照打包集成测试

use std::{
    fs::{self, File},
    io::Read,
};

use tempfile::tempdir;
use webgal_snapshot::{ErrorKind, PackerBuilder};
use zip::ZipArchive;

/// 构造一个迷你 WebGAL 项目并打包, 验证资源收集策略
#[test]
fn pack_mini_project() {
    // 构造项目
    let project = tempdir().unwrap();
    let root = project.path();
    write(&root.join("README.txt"), "readme");
    write(
        &root.join("game/config.txt"),
        "Game_name:test;\nTitle_img:title.png;\nGame_Logo:logo.png;\nTitle_bgm:title.ogg;\n",
    );
    write(
        &root.join("game/scene/start.txt"),
        "changeBg:bg1.png -next;\nbgm:theme.ogg;\nsetAnimation:idle -next;\nplayVideo:movie.mp4;\ncallScene:chapter1.txt;\n",
    );
    write(
        &root.join("game/scene/chapter1.txt"),
        "changeFigure:hero.png -next;\nchangeFigure:live/model.json -next;\n:你好 -vocal=voice1.wav;\n",
    );
    write(&root.join("game/background/title.png"), "title");
    write(&root.join("game/background/logo.png"), "logo");
    write(&root.join("game/background/bg1.png"), "bg1");
    write(&root.join("game/background/unused.png"), "unused");
    write(&root.join("game/bgm/title.ogg"), "title");
    write(&root.join("game/bgm/theme.ogg"), "theme");
    write(&root.join("game/bgm/unused.ogg"), "unused");
    write(&root.join("game/figure/hero.png"), "hero");
    write(
        &root.join("game/figure/live/model.json"),
        r#"{
            "model": "model.moc3",
            "physics": "physics.json",
            "textures": ["textures/tex.png"],
            "motions": { "idle": [{ "file": "motions/idle.motion3.json" }] },
            "expressions": [{ "name": "happy", "file": "expressions/happy.exp3.json" }]
        }"#,
    );
    write(&root.join("game/figure/live/model.moc3"), "moc3");
    write(&root.join("game/figure/live/physics.json"), "physics");
    write(&root.join("game/figure/live/textures/tex.png"), "tex");
    write(
        &root.join("game/figure/live/motions/idle.motion3.json"),
        "motion",
    );
    write(
        &root.join("game/figure/live/expressions/happy.exp3.json"),
        "expression",
    );
    write(&root.join("game/vocal/voice1.wav"), "voice1");
    write(&root.join("game/vocal/unused.wav"), "unused");
    write(&root.join("game/video/movie.mp4"), "movie");
    write(&root.join("game/animation/idle.json"), "{}");
    write(&root.join("game/animation/animationTable.json"), "{}");
    write(&root.join("game/animation/unused.json"), "{}");

    // 打包
    let destination = project.path().join("snapshot.zip");
    let result = PackerBuilder::default()
        .source(root)
        .destination(&destination)
        .run();

    assert!(result.errors.is_empty(), "打包出错: {:?}", result.errors);
    assert!(!result.aborted);
    assert_eq!(result.count, 20);
    assert!(result.total_size > 0);
    assert!(result.final_size > 0);

    // 校验压缩包内容
    let mut archive = ZipArchive::new(File::open(&destination).unwrap()).unwrap();
    let names: Vec<_> = archive.file_names().collect();
    for name in [
        "README.txt",
        "game/config.txt",
        "game/scene/start.txt",
        "game/scene/chapter1.txt",
        "game/background/title.png",
        "game/background/logo.png",
        "game/background/bg1.png",
        "game/bgm/title.ogg",
        "game/bgm/theme.ogg",
        "game/figure/hero.png",
        "game/figure/live/model.json",
        "game/figure/live/model.moc3",
        "game/figure/live/physics.json",
        "game/figure/live/textures/tex.png",
        "game/figure/live/motions/idle.motion3.json",
        "game/figure/live/expressions/happy.exp3.json",
        "game/vocal/voice1.wav",
        "game/video/movie.mp4",
        "game/animation/idle.json",
        "game/animation/animationTable.json",
    ] {
        assert!(names.contains(&name), "压缩包缺少文件: {name}");
    }
    // 未被引用的资源不应打包
    for name in [
        "game/background/unused.png",
        "game/bgm/unused.ogg",
        "game/vocal/unused.wav",
        "game/animation/unused.json",
    ] {
        assert!(!names.contains(&name), "不应打包未引用的文件: {name}");
    }
    // 校验压缩包可读取且内容完整
    let mut content = String::new();
    archive
        .by_name("game/scene/start.txt")
        .unwrap()
        .read_to_string(&mut content)
        .unwrap();
    assert!(content.starts_with("changeBg:bg1.png"));
}

/// 缺失打包目录或输出位置时报错
#[test]
fn builder_requires_source_and_destination() {
    let result = PackerBuilder::default().run();
    assert_eq!(result.errors.len(), 1);
    assert!(matches!(&result.errors[0].detail, ErrorKind::MissingSource));

    let result = PackerBuilder::default().source(".").run();
    assert_eq!(result.errors.len(), 1);
    assert!(matches!(
        &result.errors[0].detail,
        ErrorKind::MissingDestination
    ));
}

fn write(path: &std::path::Path, content: &str) {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).unwrap();
    }
    fs::write(path, content).unwrap();
}
